// Typed Taddy API client: graphql-request transport + documents generated by GraphQL Code Generator. Node 20+ (running the codegen needs Node 22+).
// Server-side only: the API key must never reach a browser or mobile bundle.
//
// Setup (see references/graphql-client-libraries.md):
//   npm i graphql graphql-request graphql-tag @graphql-typed-document-node/core
//   npm i -D @graphql-codegen/cli @graphql-codegen/typescript-operations @graphql-codegen/typescript-document-nodes
//   copy scripts/codegen.ts and scripts/graphql/ (fragments, queries) into the project, then: npx graphql-codegen --config graphql/codegen.ts
//   (the codegen introspects https://api.taddy.org, so it needs network access when it runs)
//
// Usage:
//   import { query } from "./taddy_client_typed";
//   import { GetPodcastSeries, type GetPodcastSeriesQuery, type GetPodcastSeriesQueryVariables } from "./graphql/operations";
//   const data = await query<GetPodcastSeriesQuery, GetPodcastSeriesQueryVariables>(GetPodcastSeries, { name: "The Daily" });
//   data.getPodcastSeries?.episodes?.[0]?.audioUrl  // fully typed
//
// With the @graphql-codegen/typed-document-node plugin instead of typescript-document-nodes, the generics are
// inferred from the document and can be dropped: query(GetPodcastSeriesDocument, { name: "The Daily" }).
//
// Options: { timeoutMs = 30000, signal }. A request that exceeds timeoutMs throws TaddyError with code TIMEOUT;
// timeoutMs: 0 disables the deadline. A caller-supplied signal is honoured alongside the timeout.
// Pass { timeoutMs: 300_000 } for GetEpisodeTranscript only: on-demand transcription can take minutes.
//
// Env: TADDY_USER_ID, TADDY_API_KEY (required). The endpoint is always https://api.taddy.org.

import { ClientError, GraphQLClient } from "graphql-request";
import type { DocumentNode } from "graphql";
import type { TypedDocumentNode } from "@graphql-typed-document-node/core";

const TADDY_API_URL = "https://api.taddy.org";

export class TaddyError extends Error {
  code?: string;   // e.g. API_RATE_LIMIT_EXCEEDED, QUERY_TOO_COMPLEX, HTTP_ERROR, TIMEOUT, MISSING_CREDENTIALS
  status?: number; // HTTP status
  errors?: unknown[]; // raw errors[] from the response, if any
  constructor(message: string, opts: { code?: string; status?: number; errors?: unknown[] } = {}) {
    super(message);
    this.name = "TaddyError";
    this.code = opts.code;
    this.status = opts.status;
    this.errors = opts.errors;
  }
}

let client: GraphQLClient | undefined;

function getClient(): GraphQLClient {
  if (client) return client;
  const userId = process.env.TADDY_USER_ID;
  const apiKey = process.env.TADDY_API_KEY;
  if (!userId || !apiKey) {
    throw new TaddyError("TADDY_USER_ID and TADDY_API_KEY must be set", { code: "MISSING_CREDENTIALS" });
  }
  client = new GraphQLClient(TADDY_API_URL, {
    headers: { "X-USER-ID": String(userId), "X-API-KEY": apiKey },
  });
  return client;
}

type TaddyGraphQLError = { message?: string; code?: string; extensions?: { code?: string } };

// Combine the caller's signal (if any) with a deadline. timeoutMs <= 0 or Infinity means no deadline.
function requestSignal(signal: AbortSignal | undefined, timeoutMs: number): AbortSignal | undefined {
  const hasTimeout = Number.isFinite(timeoutMs) && timeoutMs > 0;
  if (!hasTimeout) return signal;
  const timeout = AbortSignal.timeout(timeoutMs);
  return signal ? AbortSignal.any([signal, timeout]) : timeout;
}

export async function query<TData, TVariables extends Record<string, unknown> = Record<string, never>>(
  document: DocumentNode | TypedDocumentNode<TData, TVariables>,
  variables?: TVariables,
  { signal, timeoutMs = 30_000 }: { signal?: AbortSignal; timeoutMs?: number } = {},
): Promise<TData> {
  try {
    return await getClient().request<TData, TVariables>({
      document,
      variables,
      signal: requestSignal(signal, timeoutMs),
    } as never);
  } catch (err) {
    // AbortSignal.timeout() rejects with a TimeoutError; a caller's abort (AbortError) and network errors pass through.
    if (err instanceof Error && err.name === "TimeoutError") {
      throw new TaddyError(`Taddy API timed out after ${timeoutMs}ms`, { code: "TIMEOUT" });
    }
    if (err instanceof ClientError) {
      const errors = (err.response.errors ?? []) as TaddyGraphQLError[];
      const first = errors[0];
      // Taddy puts the code at errors[].code (top level); extensions.code is the fallback.
      const code = first?.code ?? first?.extensions?.code ?? (errors.length ? undefined : "HTTP_ERROR");
      throw new TaddyError(first?.message ?? `Taddy API HTTP ${err.response.status}`, {
        code,
        status: err.response.status,
        errors,
      });
    }
    throw err;
  }
}
